@page "/apply"
@rendermode InteractiveServer
@using sv_1bcf303f33974261bbf2d37f9e6c08b3.Models
@using sv_1bcf303f33974261bbf2d37f9e6c08b3.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)" role="button" tabindex="0">
            <span class="step-number">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</nav>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger" role="alert">@ErrorMessage</div>
}

@* Step Content *@
<div class="step-content">
    @switch (CurrentStep)
    {
        case 0:
            @* Step 1: Personal Info *@
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" class="form-control" @bind="FullName" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" class="form-control" @bind="Email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" class="form-control" @bind="Phone" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" class="form-control" @bind="Address" />
            </div>
            <div class="form-buttons">
                <button class="btn btn-primary" @onclick="NextStep" disabled="@IsProcessing">
                    @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
                </button>
            </div>
            break;

        case 1:
            @* Step 2: Work History *@
            <h2>Work History</h2>
            @for (int i = 0; i < WorkEntries.Count; i++)
            {
                var index = i;
                <fieldset class="work-entry">
                    <legend>Position @(index + 1)</legend>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" class="form-control" @bind="WorkEntries[index].Company" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" class="form-control" @bind="WorkEntries[index].Title" />
                    </div>
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" class="form-control" @bind="WorkEntries[index].StartDate" />
                    </div>
                    <div class="form-group">
                        <label>
                            <input type="checkbox" @bind="WorkEntries[index].IsCurrent" /> Currently working here
                        </label>
                    </div>
                    @if (!WorkEntries[index].IsCurrent)
                    {
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" class="form-control" @bind="WorkEntries[index].EndDate" />
                        </div>
                    }
                    <div class="form-group">
                        <label>Description *</label>
                        <textarea class="form-control" @bind="WorkEntries[index].Description" rows="3"></textarea>
                    </div>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </fieldset>
            }
            <button class="btn btn-secondary" @onclick="AddWorkEntry">Add Another Position</button>
            <div class="form-buttons">
                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
            break;

        case 2:
            @* Step 3: References *@
            <h2>References</h2>
            @for (int i = 0; i < References.Count; i++)
            {
                var index = i;
                <fieldset class="reference-entry">
                    <legend>Reference @(index + 1)</legend>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" class="form-control" @bind="References[index].Name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" class="form-control" @bind="References[index].Relationship" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" class="form-control" @bind="References[index].Email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" class="form-control" @bind="References[index].Phone" />
                    </div>
                    @if (References.Count > 2)
                    {
                        <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </fieldset>
            }
            @if (References.Count < 3)
            {
                <button class="btn btn-secondary" @onclick="AddReference">Add Reference</button>
            }
            <div class="form-buttons">
                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
            break;

        case 3:
            @* Step 4: Cover Letter *@
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter below:</label>
                <textarea id="coverLetter" class="form-control cover-letter-input" @bind="CoverLetter" @bind:event="oninput" rows="12" maxlength="2000"></textarea>
                <div class="character-count">@CoverLetter.Length / 2000 characters</div>
            </div>
            <div class="form-buttons">
                <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
            break;

        case 4:
            @* Step 5: Review & Submit *@
            <h2>Review & Submit</h2>

            @if (IsSubmitted)
            {
                <div class="alert alert-success">
                    <h3>Application Submitted Successfully!</h3>
                    <p>Your application ID is: <strong>@SubmittedApplicationId</strong></p>
                    <p>Thank you for applying. We will be in touch soon.</p>
                </div>
            }
            else
            {
                <section class="review-section">
                    <h3>Personal Information <a class="edit-link" @onclick="() => GoToStep(0)">Edit</a></h3>
                    <dl>
                        <dt>Full Name</dt><dd>@FullName</dd>
                        <dt>Email</dt><dd>@Email</dd>
                        <dt>Phone</dt><dd>@Phone</dd>
                        <dt>Address</dt><dd>@Address</dd>
                    </dl>
                </section>

                <section class="review-section">
                    <h3>Work History <a class="edit-link" @onclick="() => GoToStep(1)">Edit</a></h3>
                    @foreach (var entry in WorkEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span>@entry.StartDate.ToString("MMM yyyy") &mdash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span><br />
                            <p>@entry.Description</p>
                        </div>
                    }
                </section>

                <section class="review-section">
                    <h3>References <a class="edit-link" @onclick="() => GoToStep(2)">Edit</a></h3>
                    @foreach (var reference in References)
                    {
                        <div class="review-reference">
                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
                            Email: @reference.Email | Phone: @reference.Phone
                        </div>
                    }
                </section>

                <section class="review-section">
                    <h3>Cover Letter <a class="edit-link" @onclick="() => GoToStep(3)">Edit</a></h3>
                    <p class="cover-letter-preview">@CoverLetter</p>
                </section>

                <div class="form-buttons">
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @if (IsProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                    </button>
                </div>
            }
            break;
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private string ErrorMessage { get; set; } = string.Empty;
    private bool IsProcessing { get; set; }
    private bool IsSubmitted { get; set; }
    private int? SubmittedApplicationId { get; set; }

    // Step 1: Personal Info
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string CoverLetter { get; set; } = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            CurrentStep = stepIndex;
            ErrorMessage = string.Empty;
        }
    }

    private void GoToStep(int stepIndex)
    {
        CurrentStep = stepIndex;
        ErrorMessage = string.Empty;
    }

    private async Task NextStep()
    {
        ErrorMessage = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (CurrentStep == 0)
        {
            IsProcessing = true;
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            IsProcessing = false;

            if (!emailValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }

        CurrentStep++;
    }

    private void PreviousStep()
    {
        ErrorMessage = string.Empty;
        if (CurrentStep > 0)
            CurrentStep--;
    }

    private bool ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
                    string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
                {
                    ErrorMessage = "All fields are required.";
                    return false;
                }
                break;
            case 1:
                foreach (var entry in WorkEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
                    {
                        ErrorMessage = "Please complete all required fields for each work entry.";
                        return false;
                    }
                }
                break;
            case 2:
                foreach (var reference in References)
                {
                    if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                        string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
                    {
                        ErrorMessage = "Please complete all required fields for each reference.";
                        return false;
                    }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetter))
                {
                    ErrorMessage = "Please write a cover letter.";
                    return false;
                }
                break;
        }
        return true;
    }

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        IsProcessing = true;
        ErrorMessage = string.Empty;

        var personal = new PersonalInfo(FullName, Email, Phone, Address);
        var workHistory = new WorkHistory(WorkEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
        var references = References.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, references, CoverLetter);

        SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        IsSubmitted = true;
        IsProcessing = false;
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 1.5rem 0 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
    font-weight: bold;
}

.step.completed {
    opacity: 0.85;
    cursor: pointer;
}

.step.completed:hover {
    opacity: 1;
}

.step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background-color: #dee2e6;
    color: #495057;
    font-size: 0.875rem;
    margin-bottom: 0.25rem;
}

.step.active .step-number {
    background-color: #0d6efd;
    color: white;
}

.step.completed .step-number {
    background-color: #198754;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 5rem;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background-color: #dee2e6;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.25rem;
}

.step-connector.completed {
    background-color: #198754;
}

.checkmark {
    font-weight: bold;
}

.step-content {
    max-width: 700px;
    margin: 0 auto;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 1rem;
}

.form-buttons {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 1rem;
}

.btn-primary { background-color: #0d6efd; color: white; }
.btn-primary:hover { background-color: #0b5ed7; }
.btn-secondary { background-color: #6c757d; color: white; }
.btn-outline-secondary { background: transparent; border: 1px solid #6c757d; color: #6c757d; }
.btn-danger { background-color: #dc3545; color: white; }
.btn-success { background-color: #198754; color: white; }
.btn-success:hover { background-color: #157347; }
.btn-lg { padding: 0.75rem 2rem; font-size: 1.1rem; }
.btn-sm { padding: 0.25rem 0.75rem; font-size: 0.875rem; }
.btn:disabled { opacity: 0.65; cursor: not-allowed; }

.alert { padding: 1rem; border-radius: 0.375rem; margin-bottom: 1rem; }
.alert-danger { background-color: #f8d7da; color: #842029; border: 1px solid #f5c2c7; }
.alert-success { background-color: #d1e7dd; color: #0f5132; border: 1px solid #badbcc; }

.work-entry, .reference-entry {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.work-entry legend, .reference-entry legend {
    font-weight: 600;
    font-size: 0.95rem;
    padding: 0 0.5rem;
    width: auto;
}

.cover-letter-input {
    resize: vertical;
    min-height: 200px;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.review-section h3 {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.edit-link {
    font-size: 0.85rem;
    color: #0d6efd;
    cursor: pointer;
    text-decoration: underline;
}

.review-section dl {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.25rem 1rem;
    margin: 0.5rem 0;
}

.review-section dt { font-weight: 500; color: #6c757d; }
.review-section dd { margin: 0; }

.review-work-entry, .review-reference {
    margin: 0.75rem 0;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 0.25rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 0.25rem;
}

